def parse_min_should_match(num_clauses: int, spec: str) -> int:
    """
    This function parses the "min should match" specification (commonly referred to as 'mm' spec) from Solr's search engine configuration 
    and calculates the minimum number of clauses that must match based on the given specification and the total number of clauses. 
    It supports both absolute and percentage-based specifications, as well as conditional specifications using '<'.

    Parameters
    ----------
    num_clauses : int
        The total number of clauses in the query.
    spec : str
        The 'min should match' specification as a string, which can include absolute numbers, percentages, and conditional expressions.

    Returns
    -------
    int
        The calculated minimum number of clauses that must match according to the 'mm' spec.
    """

    def checked_parse_int(s: str, default: int = 0) -> int:
        """Safely convert a string to an integer, returning a default value if the conversion fails."""
        try:
            return int(s)
        except ValueError:
            return default

    def parse_percentage(s: str) -> float:
        """Parse a percentage string and return the corresponding decimal value."""
        return checked_parse_int(s.replace('%', '')) / 100

    def parse_clause(s: str) -> int:
        """Parse a clause string and return the corresponding integer value."""
        return checked_parse_int(s)

    def parse_spec(spec: str) -> int:
        """Parse the 'min should match' specification and return the corresponding minimum number of clauses."""
        parts = spec.split('<')
        if len(parts) == 1:
            # No '<' operator, assume absolute or percentage-based specification
            if spec.endswith('%'):
                # Percentage-based specification
                return max(1, int(num_clauses * parse_percentage(spec[:-1])))
            else:
                # Absolute specification
                return max(1, parse_clause(spec))
        else:
